-- Polestar.LocalNames: NPC and object names in the client's language, from
-- the load-on-demand data addon Polestar_Names (generated by
-- `node tools/polestar.js names build`: one file per language, and the client
-- loads only its own). Contract: docs/ARCHITECTURE.md, "Names in the client's
-- language".
--
--   Polestar.LocalName(kind, id, english) -> name
--     kind "npc" | "object". The client's name for the id, else `english`:
--     in an English client, for an id the pack has no name for, and while the
--     pack is not installed or not loaded. The first call in a client whose
--     language the pack has (its TOC's X-Locales, read without loading it)
--     loads the pack through Data.Pack; an English client never loads it. In
--     combat the load waits for the fight to end (the English shows
--     meanwhile), then NAMES_CHANGED fires and what shows names redraws.
--   LocalNames.Register(locale, npcs, objects)  -- the data addon's one call
--   LocalNames.IsLoaded() -> bool

local ADDON, ns = ...

local LocalNames = {}
ns.LocalNames = LocalNames

local PACK = "Polestar_Names"

local type, pcall = type, pcall
local gmatch = string.gmatch

local readable = ns.Compat.Readable

local names -- { npc = { [id] = name }, object = { ... } } once the pack registered
-- nil: not tried yet; "off": nothing to load (English client, pack missing or
-- refused); "combat": waiting for the end of the fight; "loaded".
local state

local function clientLocale()
	local ok, locale = pcall(GetLocale)
	return ok and type(locale) == "string" and locale or "enUS"
end

function LocalNames.Register(locale, npcs, objects)
	if locale ~= clientLocale() then return end
	names = { npc = type(npcs) == "table" and npcs or {}, object = type(objects) == "table" and objects or {} }
end

function LocalNames.IsLoaded()
	return names ~= nil
end

-- Whether the pack has a file for the client's language (its TOC's X-Locales).
local function packHasLocale()
	local get = C_AddOns and C_AddOns.GetAddOnMetadata
	if not get then return false end
	local ok, list = pcall(get, PACK, "X-Locales")
	list = ok and readable(list) or nil
	if type(list) ~= "string" then return false end
	local locale = clientLocale()
	for l in gmatch(list, "%a+") do
		if l == locale then return true end
	end
	return false
end

local afterCombat

local function load()
	local ok, reason = ns.Data.Pack(PACK)
	if ok then
		state = names and "loaded" or "off"
	elseif reason == "combat" then
		state = "combat"
		ns.RegisterEvent("PLAYER_REGEN_ENABLED", afterCombat)
	else
		state = "off"
	end
end

function afterCombat()
	ns.UnregisterEvent("PLAYER_REGEN_ENABLED", afterCombat)
	load()
	if state == "loaded" then ns.Fire("NAMES_CHANGED") end
end

function ns.LocalName(kind, id, english)
	if type(id) ~= "number" then return english end
	if state ~= "loaded" then
		if state == nil then
			if packHasLocale() then load() else state = "off" end
		end
		if state ~= "loaded" then return english end
	end
	local byId = names[kind]
	return byId and byId[id] or english
end
